function uniqueShipmentEvents(events) {
  return events.filter((event, index) => events.findIndex((candidate) => candidate.shipmentId === event.shipmentId) === index);
}
module.exports = { uniqueShipmentEvents };

problems.solutionCode:
function uniqueShipmentEvents(events) {
  const seenShipmentIds = new Set();
  const uniqueEvents = [];
  for (const event of events) {
    if (seenShipmentIds.has(event.shipmentId)) continue;
    seenShipmentIds.add(event.shipmentId);
    uniqueEvents.push(event);
  }
  return uniqueEvents;
}
module.exports = { uniqueShipmentEvents };

