problems.starterCode:
function joinInvoiceEvents(events, invoices) {
  return events.filter((event) => invoices.some((invoice) => invoice.invoiceId === event.invoiceId));
}
module.exports = { joinInvoiceEvents };

problems.solutionCode:
function joinInvoiceEvents(events, invoices) {
  const invoiceIds = new Set();
  for (const invoice of invoices) invoiceIds.add(invoice.invoiceId);
  return events.filter((event) => invoiceIds.has(event.invoiceId));
}
module.exports = { joinInvoiceEvents };

