problems.starterCode:
function summarizeCarrierScans(scans) {
  const summaries = [];
  for (const scan of scans) {
    const existing = summaries.find((summary) => summary.routeId === scan.routeId);
    if (existing) existing.scanCount += 1;
    else summaries.push({ routeId: scan.routeId, scanCount: 1 });
  }
  return summaries;
}
module.exports = { summarizeCarrierScans };

problems.solutionCode:
function summarizeCarrierScans(scans) {
  const countsByRoute = new Map();
  for (const scan of scans) {
    countsByRoute.set(scan.routeId, (countsByRoute.get(scan.routeId) ?? 0) + 1);
  }
  return Array.from(countsByRoute, ([routeId, scanCount]) => ({ routeId, scanCount }));
}
module.exports = { summarizeCarrierScans };

